function simulate(dt){if(paused)return;eco.oxygen=Math.max(0,Math.min(100,eco.oxygen+dt*(eco.plants*eco.light/100*.055-eco.fish*.035)));eco.food=Math.max(0,eco.food-dt*eco.fish*.012)}
function render(){$('screen').innerHTML='<div class="jar-scene"><canvas id="world" width="440" height="196" aria-label="生态瓶画面"></canvas><span id="eco-stats"></span></div><div class="eco-tools"><button id="plant">种水草 '+eco.plants+'</button><button id="feed">投喂</button><button id="light">光照 '+eco.light+'%</button><button id="pause">'+(paused?'继续':'暂停')+'</button><button id="save" '+(!loaded||saving?'disabled':'')+'>保存</button></div><div class="foot">简化生态模型 · 氧气随光照和生物数量变化</div>'+notice();$('plant').onclick=()=>{eco.plants=Math.min(16,eco.plants+1);render()};$('feed').onclick=()=>{eco.food=Math.min(100,eco.food+20);render()};$('light').onclick=()=>{eco.light=eco.light===100?20:eco.light+20;render()};$('pause').onclick=()=>{paused=!paused;render()};$('save').onclick=()=>saveStore({...eco});wire();draw(performance.now())}
function draw(t){let c=$('world');if(!c)return;let g=c.getContext('2d'),w=440,h=196;g.clearRect(0,0,w,h);let bg=g.createLinearGradient(0,0,0,h);bg.addColorStop(0,'#244d5e');bg.addColorStop(1,'#102e36');g.fillStyle=bg;g.fillRect(0,0,w,h);g.strokeStyle='#8cc6cd22';for(let i=0;i<18;i++){let x=(i*31+Math.sin(t*.0005+i)*6)%440,y=196-(t*.008+i*17)%190;g.beginPath();g.arc(x,y,1+i%3,0,7);g.stroke()}g.fillStyle='#82775c';g.beginPath();g.moveTo(0,182);for(let x=0;x<=440;x+=10)g.lineTo(x,178+Math.sin(x*.04)*4);g.lineTo(440,196);g.lineTo(0,196);g.fill();for(let i=0;i<eco.plants;i++){let x=28+i*27%400;g.strokeStyle=['#5d9b82','#88b19a','#4d857b'][i%3];g.lineWidth=3;g.beginPath();g.moveTo(x,180);g.bezierCurveTo(x-12,156,x+12+Math.sin(t*.001+i)*6,136,x+Math.sin(t*.001+i)*7,116-i%4*11);g.stroke()}for(let i=0;i<eco.fish;i++){let speed=eco.oxygen<20?.00015:.00035,x=220+Math.sin(t*speed+i*1.37)*165,y=65+i%4*23+Math.sin(t*.001+i)*7,dir=Math.cos(t*speed+i*1.37)>0?1:-1;g.save();g.translate(x,y);g.scale(dir,1);g.fillStyle=['#d9b485','#a4c9cb','#da997f'][i%3];g.beginPath();g.ellipse(0,0,9,4,0,0,7);g.fill();g.beginPath();g.moveTo(-7,0);g.lineTo(-14,-5);g.lineTo(-14,5);g.fill();g.fillStyle='#172c31';g.fillRect(4,-2,1.5,1.5);g.restore()}$('eco-stats').textContent='氧气 '+Math.round(eco.oxygen)+'% · 食物 '+Math.round(eco.food)+'%'+(eco.oxygen<20?' · 缺氧，增加水草或光照':'')}
function loop(t){if(!alive)return;let dt=Math.min(.1,(t-(last||t))/1000);last=t;simulate(dt);draw(t);frame=requestAnimationFrame(loop)}setBack(home);render();readStore();frame=requestAnimationFrame(loop);
